def validar_sintaxis(contenido: str, nombre: str) -> bool:
    if not nombre.endswith('.py'): return True
    try:
        import ast
        ast.parse(contenido)
        return True
    except SyntaxError as e:
        print(f"{Color.ROJO}[ERROR SINTAXIS]{Color.RESET} {nombre}: {e}")
        return False

def accion_create(op: dict[str, Any], ruta: Path) -> None:
    if DRY_RUN:
        print(f"{Color.MAGENTA}[DRY-RUN]{Color.RESET} Crearía archivo: {ruta}")
        return
    content = op.get('content', '')
    if not validar_sintaxis(content, ruta.name):
        print(f"{Color.AMARILLO}[AVISO]{Color.RESET} Abortando creación de {ruta.name} por error de sintaxis.")
        return
    ruta.write_text(content, encoding='utf-8')
    print(f"{Color.VERDE}[CREADO]{Color.RESET} {ruta}")

