def accion_delete_full(op: dict[str, Any], ruta: Path) -> None:
    if ruta.exists():
        ruta.unlink()
        print(f"{Color.ROJO}[ELIMINADO]{Color.RESET} {ruta}")
        # Limpiar backup asociado
        bak = ruta.with_suffix(ruta.suffix + '.bak')
        if bak.exists():
            bak.unlink()
            print(f"{Color.AMARILLO}[LIMPIEZA]{Color.RESET} Backup eliminado: {bak.name}")

def accion_rename(op: dict[str, Any], ruta: Path) -> None:
    nueva_ruta = Path(op.get('to', ''))
    if not nueva_ruta: return
    if DRY_RUN:
        print(f"{Color.MAGENTA}[DRY-RUN]{Color.RESET} Renombraría {ruta} a {nueva_ruta}")
        return
    if ruta.exists():
        shutil.move(str(ruta), str(nueva_ruta))
        print(f"{Color.VERDE}[RENOMBRADO]{Color.RESET} {ruta} -> {nueva_ruta}")
